import {
  Group,
  PlaneGeometry,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  DoubleSide,
  AdditiveBlending,
} from 'three/webgpu';
import {
  uv,
  mix,
  vec3,
  normalWorld,
  viewDirection,
  dot,
  clamp,
  Fn,
  texture,
  uniform,
  time,
  sin,
  positionWorld,
  cameraPosition,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.handlers = {};
  group.userData.cleanup = () => {};

  // Determine badge size from source rect aspect ratio (512x320 -> 1.6)
  const aspect = 512 / 320; // 1.6
  const badgeWidth = 0.6;
  const badgeHeight = badgeWidth / aspect;

  // Load texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const texUniform = uniform(null); // placeholder, will be set when texture loads

  // --- Main badge plane (PBR material with fresnel accent edge) ---
  const mainMaterial = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.3,
    color: 0xe8ecf2, // fallback
    side: DoubleSide,
  });

  // Fresnel edge glow using TSL
  const accentColor = new ctx.THREE.Color(config.intent?.visualSpec?.colors?.accent || '#ff2a38');
  const fresnelNode = Fn(() => {
    const ndotv = dot(normalWorld, normalize(viewDirection));
    const fresnel = clamp(1.0 - ndotv, 0.0, 1.0);
    return mix(vec3(0.0), accentColor.toArray(), fresnel * 1.2);
  })();
  mainMaterial.emissiveNode = fresnelNode;

  // Map texture once loaded
  texturePromise.then((tex) => {
    const mapNode = texture(tex);
    mainMaterial.mapNode = mapNode;
    mainMaterial.needsUpdate = true;
  });

  const mainGeometry = new PlaneGeometry(badgeWidth, badgeHeight);
  const mainMesh = new ctx.THREE.Mesh(mainGeometry, mainMaterial);
  group.add(mainMesh);

  // --- Accent edge glow (back layer) ---
  const glowMaterial = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    transparent: true,
    opacity: 0.35,
    blending: AdditiveBlending,
    side: DoubleSide,
  });
  const glowGeometry = new PlaneGeometry(badgeWidth * 1.08, badgeHeight * 1.08);
  const glowMesh = new ctx.THREE.Mesh(glowGeometry, glowMaterial);
  glowMesh.position.z = -0.01; // slightly behind
  group.add(glowMesh);

  // --- Hover rise-in (0.15 units) ---
  let hoverTimeline = null;
  const originalY = group.position.y; // will be set by adapter, but we use relative motion
  // We'll store baseY for motion in userData
  group.userData.baseY = 0;

  group.userData.handlers.hover = {
    onEnter: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: group.userData.baseY + 0.15,
        duration: 0.35,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
    onLeave: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: group.userData.baseY,
        duration: 0.35,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
  };

  // --- Click press-down + emit ---
  let clickTimeline = null;
  group.userData.handlers.click = {
    onDown: () => {
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.08,
        ease: 'back.out',
      });
    },
    onUp: () => {
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.25,
        ease: 'power4.out',
      });
      ctx.emit('hub-pricing.select', { from: 'badge' });
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill all timelines
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();

    // Dispose geometries and materials
    mainGeometry.dispose();
    mainMaterial.dispose();
    glowGeometry.dispose();
    glowMaterial.dispose();

    // Clear references
    group.children.forEach((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  return group;
}
